function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 16) return 'nums needs 1 to 16 values.';
  if (!Number.isInteger(k) || k < 1 || k > nums.length) return 'k is from 1 to nums.length.';
  if (nums.length % k !== 0) return 'nums.length must be divisible by k.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > nums.length)) return 'Each value is an integer from 1 to nums.length.';
  return null;
}

