function minimumIncompatibility(nums, k) {
  const n = nums.length;
  const size = n / k;
  const full = (1 << n) - 1;
  const bits = new Array(full + 1).fill(0);
  const cost = new Array(full + 1).fill(-1);
  nums.sort((a, b) => a - b);

  for (let group = 1; group <= full; group++) {
    bits[group] = bits[group >> 1] + (group & 1);
    if (bits[group] !== size) continue;
    let first = -1;
    let previous = -1;
    let valid = true;
    for (let i = 0; i < n; i++) {
      if ((group & (1 << i)) === 0) continue;
      if (previous !== -1 && nums[previous] === nums[i]) valid = false;
      if (first === -1) first = i;
      previous = i;
    }
    if (valid) cost[group] = nums[previous] - nums[first];
  }

  const dp = new Array(full + 1).fill(Infinity);
  dp[0] = 0;
  for (let mask = 0; mask < full; mask++) {
    if (dp[mask] === Infinity) continue;
    const free = full & ~mask;
    const low = free & -free;
    const rest = free ^ low;
    for (let sub = rest; ; sub = (sub - 1) & rest) {
      const group = sub | low;
      if (cost[group] !== -1) {
        dp[mask | group] = Math.min(dp[mask | group], dp[mask] + cost[group]);
      }
      if (sub === 0) break;
    }
  }
  return dp[full] === Infinity ? -1 : dp[full];
}

