function minimumIncompatibility(nums, k) {
  // Try every way to drop the elements, one by one, into k buckets of equal size.
  const size = nums.length / k;
  const buckets = Array.from({ length: k }, () => []);
  let best = Infinity;
  const place = i => {
    if (i === nums.length) {
      let total = 0;
      for (const bucket of buckets) total += Math.max(...bucket) - Math.min(...bucket);
      best = Math.min(best, total);
      return;
    }
    for (const bucket of buckets) {
      if (bucket.length === size || bucket.includes(nums[i])) continue;
      bucket.push(nums[i]);
      place(i + 1);
      bucket.pop();
      // Empty buckets are interchangeable, so trying the first empty one is enough.
      if (bucket.length === 0) break;
    }
  };
  place(0);
  return best === Infinity ? -1 : best;
}

