function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? [12, 14, 15, 16, 16, 16][pick(6)] : 1 + pick(8);
  const divisors = [];
  for (let d = 1; d <= n; d++) if (n % d === 0) divisors.push(d);
  // Large inputs favour group sizes 2 to 8, where the search is hardest.
  const middle = divisors.filter(d => d > 1 && d < n);
  const k = size === 'large' && middle.length && rand() < 0.85 ? middle[pick(middle.length)] : divisors[pick(divisors.length)];
  const groupSize = n / k;
  let nums = [];
  if (rand() < 0.7) {
    // Build k groups of distinct values so that a valid split exists, then shuffle them together.
    for (let g = 0; g < k; g++) {
      const values = Array.from({ length: n }, (_, i) => i + 1);
      for (let i = 0; i < groupSize; i++) {
        const j = i + pick(n - i);
        [values[i], values[j]] = [values[j], values[i]];
        nums.push(values[i]);
      }
    }
    for (let i = nums.length - 1; i > 0; i--) {
      const j = pick(i + 1);
      [nums[i], nums[j]] = [nums[j], nums[i]];
    }
  } else {
    const top = 1 + pick(n);
    nums = Array.from({ length: n }, () => 1 + pick(top));
  }
  return [nums, k];
}
